  const version = /\b(\d+)\.(\d+)\.(\d+)\b/.exec(init.userAgent);
  if (version && Number(version[1]) === 0 && Number(version[2]) < 166) throw Object.assign(new Error('unsupported_codex_version'), { code: 'unsupported_codex_version' });
